import json
def signing_message(claims):
    return ('adminapps.financial.admission-capability.v1\n' + json.dumps(
        claims, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
        allow_nan=False)).encode('utf-8')
# Load the seven wire_utf8 examples preserved in this evidence JSON.
cases = next(c['cases'] for c in evidence['checks']
             if c.get('check') == 'stdlib_json_representation_diagnostic')
original = signing_message(json.loads(cases[0]['wire_utf8']))
for case in cases:
    last = json.loads(case['wire_utf8'])
    first = {}
    for key, value in json.loads(case['wire_utf8'], object_pairs_hook=lambda p: p):
        first.setdefault(key, value)
    assert (signing_message(last) == original) == case['same_reserialized_signing_message']
    assert (first != last) == case['parser_semantic_disagreement']
